<script setup lang="ts">
import type { StageEntry } from '~/types'
const route=useRoute(); const { transactions, update, setStage, totalFees, canComplete, stageRoleMap, persist }=useTransactions(); const {currentUser,can}=useAuth(); const {saveFile,openFile}=useFileStore()
const tx=computed(()=>transactions.value.find(t=>t.id===route.params.id)); const selected=ref<StageEntry|null>(null); const note=ref(''); const toast=ref('')
function notify(s:string){toast.value=s;setTimeout(()=>toast.value='',2200)}
function saveBasics(){if(!tx.value)return;update(tx.value,'تحديث البيانات الأساسية');notify('تم الحفظ')}
function selectStage(s:StageEntry){selected.value=s;note.value=s.note||''}
function allowed(s:StageEntry){return can(stageRoleMap[s.key]||['admin'])}
function completeStage(){if(!tx.value||!selected.value)return;const err=canComplete(tx.value,selected.value.key);if(err)return alert(err);if(!allowed(selected.value))return alert('لا تملك صلاحية إكمال هذه المرحلة');setStage(tx.value,selected.value.key,'done',note.value);selected.value=null;notify('تم إكمال المرحلة')}
function blockStage(){if(!tx.value||!selected.value)return;if(!allowed(selected.value))return alert('لا تملك الصلاحية');if(!note.value.trim())return alert('اكتب سبب الإيقاف');setStage(tx.value,selected.value.key,'blocked',note.value);selected.value=null}
function reopenStage(){if(!tx.value||!selected.value||currentUser.value.role!=='admin')return;setStage(tx.value,selected.value.key,'active',note.value||'إعادة فتح بواسطة المشرف');selected.value=null}
async function upload(e:Event,category:string){if(!tx.value)return;const input=e.target as HTMLInputElement;const f=input.files?.[0];if(!f)return;const id='file_'+crypto.randomUUID();await saveFile(id,f);tx.value.attachments.unshift({id,name:f.name,mime:f.type,size:f.size,category,createdAt:new Date().toISOString(),uploadedBy:currentUser.value.name});update(tx.value,`رفع ملف: ${f.name}`);input.value='';notify('تم حفظ الملف')}
function removeAttachment(id:string){if(!tx.value||currentUser.value.role!=='admin')return;tx.value.attachments=tx.value.attachments.filter(a=>a.id!==id);update(tx.value,'حذف مرفق')}
const feeTotal=computed(()=>tx.value?totalFees(tx.value):0); function fmt(n:number){return new Intl.NumberFormat('ar-IQ').format(Number(n||0))}
</script>
<template><div v-if="tx"><div class="page-head"><div><h1>معاملة {{tx.serial}}</h1><p>{{tx.companyName}} — {{tx.vehicleNumber}}</p></div><div class="right-actions"><button class="btn" @click="saveBasics">حفظ التعديلات</button><NuxtLink to="/transactions" class="btn ghost">رجوع</NuxtLink></div></div>
<div class="card" style="margin-bottom:16px"><StageTimeline :tx="tx" @select="selectStage"/><div class="progressbar"><span :style="{width:(tx.stages.filter(s=>s.status==='done').length/tx.stages.length*100)+'%'}"></span></div></div>
<div class="two-col"><div class="grid"><div class="card"><h3>بيانات المعاملة</h3><div class="form-grid"><div class="field"><label>رقم الإجراء الموحد</label><input v-model="tx.unifiedProcedureNo" class="input"></div><div class="field"><label>رقم البيان</label><input v-model="tx.declarationNo" class="input"></div><div class="field"><label>رقم المانيفست</label><input v-model="tx.manifestNo" class="input"></div><div class="field"><label>اسم السائق</label><input v-model="tx.driverName" class="input"></div><div class="field"><label>رقم السيارة</label><input v-model="tx.vehicleNumber" class="input"></div><div class="field"><label>البضاعة</label><input v-model="tx.goods" class="input"></div><div class="field full"><label>ملاحظات</label><textarea v-model="tx.notes" class="input" rows="2"></textarea></div></div></div>
<div class="card"><div class="section-title"><h3>المستندات والأرشفة</h3><span class="pill">ملف المعاملة النهائي مطلوب لإكمال الأرشفة</span></div><div class="filters"><label class="btn primary">رفع PDF نهائي<input type="file" accept="application/pdf,image/*" hidden @change="upload($event,'final')"></label><label class="btn">فاتورة<input type="file" accept="application/pdf,image/*" hidden @change="upload($event,'invoice')"></label><label class="btn">مانيفست<input type="file" accept="application/pdf,image/*" hidden @change="upload($event,'manifest')"></label><label class="btn">مرفق آخر<input type="file" accept="application/pdf,image/*" hidden @change="upload($event,'other')"></label></div><div class="table-wrap"><table class="table" style="min-width:650px"><thead><tr><th>الملف</th><th>النوع</th><th>الرافع</th><th>التاريخ</th><th></th></tr></thead><tbody><tr v-for="a in tx.attachments" :key="a.id"><td>{{a.name}}</td><td>{{a.category}}</td><td>{{a.uploadedBy}}</td><td>{{new Date(a.createdAt).toLocaleString('ar-IQ')}}</td><td><button class="btn ghost" @click="openFile(a.id)">فتح</button> <button v-if="currentUser.role==='admin'" class="btn danger" @click="removeAttachment(a.id)">حذف</button></td></tr><tr v-if="!tx.attachments.length"><td colspan="5" class="empty">لا توجد مرفقات</td></tr></tbody></table></div></div>
<div class="card"><h3>القيم المالية</h3><div class="form-grid"><div class="field"><label>قيمة الفاتورة</label><input v-model.number="tx.finance.invoiceValue" type="number" class="input"></div><div class="field"><label>العملة</label><select v-model="tx.finance.currency" class="input"><option>USD</option><option>IQD</option><option>JOD</option><option>EUR</option></select></div><div class="field"><label>القيمة الجمركية بالدينار</label><input v-model.number="tx.finance.customsValueIqd" type="number" class="input"></div><div class="field"><label>الضريبة</label><input v-model.number="tx.finance.tax" type="number" class="input"></div><div class="field"><label>الرسوم الجمركية</label><input v-model.number="tx.finance.customsFees" type="number" class="input"></div><div class="field"><label>رسوم إصدار الإقرار</label><input v-model.number="tx.finance.declarationFee" type="number" class="input"></div><div class="field"><label>رسوم أخرى</label><input v-model.number="tx.finance.otherFees" type="number" class="input"></div><div class="field wide"><label>وصف الرسوم الأخرى</label><input v-model="tx.finance.otherFeesNote" class="input"></div></div><div class="total-box" style="margin-top:14px"><small>إجمالي الضرائب والرسوم للمعاملة</small><strong>{{fmt(feeTotal)}} د.ع</strong></div></div></div>
<div class="grid"><div class="card"><h3>ملخص</h3><div class="kv"><div><small>الشركة</small><b>{{tx.companyName}}</b></div><div><small>رمز الشركة</small><b>{{tx.companyCode||'غير محدد'}}</b></div><div><small>تاريخ الإنشاء</small><b>{{new Date(tx.createdAt).toLocaleString('ar-IQ')}}</b></div></div></div><div class="card"><h3>سجل الحركة</h3><ul class="activity"><li v-for="a in tx.activities" :key="a.id"><b>{{a.action}}</b><small>{{a.userName}} — {{new Date(a.at).toLocaleString('ar-IQ')}}</small><small v-if="a.details">{{a.details}}</small></li></ul></div></div></div>
<div v-if="selected" class="modal-backdrop" @click.self="selected=null"><div class="modal"><h3>{{selected.label}}</h3><p><StatusBadge :status="selected.status"/> <span v-if="selected.completedBy">— {{selected.completedBy}}</span></p><div class="field"><label>ملاحظة / سبب</label><textarea v-model="note" class="input" rows="3"></textarea></div><div class="modal-actions"><button class="btn ghost" @click="selected=null">إغلاق</button><button v-if="selected.status!=='done'" class="btn danger" :disabled="!allowed(selected)" @click="blockStage">إيقاف</button><button v-if="selected.status!=='done'" class="btn primary" :disabled="!allowed(selected)" @click="completeStage">✓ إكمال المرحلة</button><button v-if="selected.status==='done'&&currentUser.role==='admin'" class="btn" @click="reopenStage">إعادة فتح</button></div></div></div><div v-if="toast" class="toast">{{toast}}</div></div><div v-else class="empty">المعاملة غير موجودة</div></template>
